	private static SourceStage commit(LmdbStore store, Record record, long previous, UUID predecessor)
			throws IOException {
		Statement statement = record.getStatement();
		try (var connection = store.getConnection()) {
			connection.begin(IsolationLevels.SNAPSHOT_READ);
			if (record.isAddition()) {
				connection.addStatement(statement.getSubject(), statement.getPredicate(), statement.getObject());
			} else {
				connection.removeStatements(statement.getSubject(), statement.getPredicate(), statement.getObject());
			}
			connection.commit();
		}
		byte[] actual;
		try (var input = store.getBackingStore().getTripleStore().openBackupStage(previous + 1)) {
			actual = input.readAllBytes();
		}
		Stage header;
		try (var input = new DataInputStream(new ByteArrayInputStream(actual))) {
			header = PostCommitBackupPublisher.readStage(input, null);
		}
		assertEquals(previous + 1, header.transaction);
		assertEquals(previous, header.previousTransaction);
		assertEquals(predecessor, header.predecessor);
		assertEquals(1, header.count);
		ByteArrayOutputStream expected = new ByteArrayOutputStream();
		try (DataOutputStream output = new DataOutputStream(expected)) {
			PostCommitBackupPublisher.writeStageHeader(output, header);
			LmdbBackupDeltaCodec.writeRecords(output, List.of(record));
		}
		assertArrayEquals(expected.toByteArray(), actual,
				"The actual native stage must contain exactly the public mutation");
		LmdbBackupChunkCodec.Encoder encoder = new LmdbBackupChunkCodec.Encoder();
		int length = encoder.encode(actual, actual.length);
		return new SourceStage(header, record, actual, Arrays.copyOf(encoder.bytes(), length));
	}

	private static CatalogSnapshot snapshot(TripleStore triples) throws IOException {
		return triples.getTxnManager().doWithFreshPriority((stack, transaction) -> {
			var database = stack.mallocInt(1);
			E(mdb_dbi_open(transaction, (ByteBuffer) null, 0, database));
			MDBStat statistics = MDBStat.malloc(stack);
			E(mdb_stat(transaction, database.get(0), statistics));
			NativeStatistics main = statistics(statistics);
			Map<String, byte[]> catalog = rows(stack, transaction, database.get(0));
			Map<String, NativeTree> trees = new LinkedHashMap<>();
			byte[] explicitIndex = null;
			byte[] hot = null;
			for (var row : catalog.entrySet()) {
				byte[] nativeKey = HexFormat.of().parseHex(row.getKey());
				String name = new String(nativeKey, StandardCharsets.UTF_8);
				if (name.startsWith("backup-outbox")) {
					E(mdb_dbi_open(transaction, name, 0, database));
					E(mdb_stat(transaction, database.get(0), statistics));
					trees.put(name, new NativeTree(row.getValue(), statistics(statistics),
							rows(stack, transaction, database.get(0))));
				} else if (name.equals(TripleIndex.nativeDatabaseName("spoc", true))) {
					explicitIndex = row.getValue();
				} else if (Arrays.equals(LmdbBackupCatalogTestSupport.KEY, nativeKey)) {
					hot = row.getValue();
				}
			}
			return new CatalogSnapshot(main, trees, explicitIndex, hot);
		});
	}

	private static Map<String, byte[]> rows(MemoryStack stack, long transaction, int database) throws IOException {
		var handle = stack.mallocPointer(1);
		E(mdb_cursor_open(transaction, database, handle));
		long cursor = handle.get(0);
		MDBVal key = MDBVal.malloc(stack);
		MDBVal value = MDBVal.malloc(stack);
		Map<String, byte[]> result = new LinkedHashMap<>();
		try {
			int status = mdb_cursor_get(cursor, key, value, MDB_FIRST);
			while (status == MDB_SUCCESS) {
				result.put(HexFormat.of().formatHex(copy(key)), copy(value));
				status = mdb_cursor_get(cursor, key, value, MDB_NEXT);
			}
			E(status);
		} finally {
			mdb_cursor_close(cursor);
		}
		return result;
	}

	private static byte[] copy(MDBVal value) {
		ByteBuffer source = Objects.requireNonNull(value.mv_data()).duplicate();
		byte[] bytes = new byte[source.remaining()];
		source.get(bytes);
		return bytes;
	}

	private static NativeStatistics statistics(MDBStat statistics) {
		return new NativeStatistics(statistics.ms_psize(), statistics.ms_depth(), statistics.ms_branch_pages(),
				statistics.ms_leaf_pages(), statistics.ms_overflow_pages(), statistics.ms_entries());
	}

	private static Pack pack(byte[] encoded) {
		ByteBuffer bytes = ByteBuffer.wrap(encoded).order(ByteOrder.BIG_ENDIAN);
		assertEquals(PACK_MAGIC, bytes.getInt());
		int count = bytes.getInt();
		assertTrue(count >= 0 && count <= 128);
		List<Frame> frames = new ArrayList<>();
		long previous = 0;
		for (int index = 0; index < count; index++) {
			long transaction = bytes.getLong();
			int length = bytes.getInt();
			assertTrue(transaction > previous);
			assertTrue(length > 0 && length <= 256);
			byte[] frame = new byte[length];
			bytes.get(frame);
			frames.add(new Frame(transaction, frame));
			previous = transaction;
		}
		assertEquals(Integer.BYTES, bytes.remaining());
		CRC32C checksum = new CRC32C();
		checksum.update(encoded, 0, encoded.length - Integer.BYTES);
		assertEquals((int) checksum.getValue(), bytes.getInt());
		return new Pack(encoded, frames);
	}

	private static void assertPackStages(Pack pack, Map<Long, SourceStage> stages) throws IOException {
		for (Frame frame : pack.frames()) {
			SourceStage expected = stages.get(frame.transaction());
			assertNotNull(expected);
			assertArrayEquals(expected.frame(), frame.bytes(),
					"Packed bytes must match the real canonical source frame");
			byte[] decoded = new byte[LmdbBackupChunkCodec.decodedLength(frame.bytes(), frame.bytes().length, true)];
			LmdbBackupChunkCodec.decode(frame.bytes(), frame.bytes().length, true, decoded);
			assertArrayEquals(expected.bytes(), decoded);
		}
	}

	private static List<String> changedDescriptors(CatalogSnapshot before, CatalogSnapshot after) {
		List<String> changed = new ArrayList<>();
		for (var tree : before.trees().entrySet()) {
			NativeTree replacement = after.trees().get(tree.getKey());
			if (replacement == null || !Arrays.equals(tree.getValue().descriptor(), replacement.descriptor())) {
				changed.add(tree.getKey());
			}
		}
		return changed;
	}

	private static void assertRawRouteUnchanged(SourceStage raw, CatalogSnapshot before, CatalogSnapshot after) {
		String destination = LmdbBackupOutbox.bucketDatabaseName((int) (raw.header().transaction & (BUCKETS - 1)));
		String rawKey = key(raw.header().transaction, 0);
		assertArrayEquals(raw.frame(), before.trees().get(destination).rows().get(rawKey));
		assertArrayEquals(raw.frame(), after.trees().get(destination).rows().get(rawKey));
		for (String name : before.trees().keySet()) {
			if (!name.equals(destination)) {
				assertFalse(before.trees().get(name).rows().containsKey(rawKey),
						"The raw chunk must retain its original bucket route");
				assertFalse(after.trees().get(name).rows().containsKey(rawKey),
						"Packed rollover must not relocate the raw chunk");
			}
		}
	}

	private static String key(long first, long second) {
		return HexFormat.of()
				.formatHex(ByteBuffer.allocate(2 * Long.BYTES)
						.order(ByteOrder.BIG_ENDIAN)
						.putLong(first)
						.putLong(second)
						.array());
	}

	private static void assertSingleLeaf(NativeStatistics statistics, String description) {
		assertEquals(1, statistics.depth(), description + " must have depth one");
		assertEquals(1L, statistics.leaves(), description + " must have one leaf");
		assertEquals(0L, statistics.branches(), description + " must not add a branch write");
		assertEquals(0L, statistics.overflow(), description + " must not hide source cost in overflow pages");
	}

	private static void assertPublished(LmdbStore store, Path backups, long baseline, long head, UUID generation,
			Map<Long, SourceStage> stages, Path destination) throws IOException {
		List<Path> logs = ((LmdbBackupServiceImpl) store.getBackupService()).exportTransactionLogs(backups, baseline,
				head, destination);
		assertEquals(stages.size(), logs.size());
		int index = 0;
		for (SourceStage stage : stages.values()) {
			ByteArrayOutputStream expected = new ByteArrayOutputStream();
			LmdbBackupDeltaCodec.write(expected, List.of(stage.record()), stage.header().previousTransaction,
					generation);
			try (var input = new GZIPInputStream(Files.newInputStream(logs.get(index++)))) {
				assertArrayEquals(expected.toByteArray(), input.readAllBytes(),
						"Every normal exported journal must preserve the exact mutation, predecessor and generation");
			}
		}
	}

	private static void assertContents(LmdbStore store, Set<Statement> expected) {
		try (var connection = store.getConnection()) {
			assertEquals((long) expected.size(), connection.size());
			for (Statement statement : expected) {
				assertTrue(connection.hasStatement(statement.getSubject(), statement.getPredicate(),
						statement.getObject(), false));
			}
		}
	}

	private static List<Statement> benchmarkStatements() {
		var values = SimpleValueFactory.getInstance();
		var predicate = values.createIRI("urn:backup-throughput:predicate:0");
		List<Statement> statements = new ArrayList<>();
		for (int index = 0; index < SLOTS; index++) {
			statements.add(values.createStatement(values.createIRI("urn:backup-throughput:subject:" + index), predicate,
					values.createLiteral("precomputed-value-" + index)));
		}
		return statements;
	}

	private static Statement rawStatement() {
		var values = SimpleValueFactory.getInstance();
		Random random = new Random(0x52345031L);
		String alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
		StringBuilder label = new StringBuilder(1024);
		for (int index = 0; index < 1024; index++) {
			label.append(alphabet.charAt(random.nextInt(alphabet.length())));
		}
		return values.createStatement(values.createIRI("urn:raw-route:subject"),
				values.createIRI("urn:raw-route:predicate"),
				values.createLiteral(label.toString()));
	}

	private record SourceStage(Stage header, Record record, byte[] bytes, byte[] frame) {
	}

	private record Frame(long transaction, byte[] bytes) {
	}

	private record Pack(byte[] bytes, List<Frame> frames) {
	}

	private record NativeStatistics(int pageSize, int depth, long branches, long leaves, long overflow, long entries) {
	}

	private record NativeTree(byte[] descriptor, NativeStatistics statistics, Map<String, byte[]> rows) {
	}

	private record CatalogSnapshot(NativeStatistics main, Map<String, NativeTree> trees, byte[] explicitIndex,
			byte[] hot) {
	}
